def transform(grid):
    h, w = len(grid), len(grid[0])
    bg = max(set(x for row in grid for x in row),
             key=lambda x: sum(row.count(x) for row in grid))
    pts = sorted((r, c) for r in range(h) for c in range(w)
                 if grid[r][c] != bg)

    def cross(o, a, b):
        return (a[0] - o[0]) * (b[1] - o[1]) - (a[1] - o[1]) * (b[0] - o[0])

    lo = []
    for p in pts:
        while len(lo) >= 2 and cross(lo[-2], lo[-1], p) <= 0:
            lo.pop()
        lo.append(p)
    hi = []
    for p in reversed(pts):
        while len(hi) >= 2 and cross(hi[-2], hi[-1], p) <= 0:
            hi.pop()
        hi.append(p)
    hull = lo[:-1] + hi[:-1]

    def inside(r, c):
        p = (r, c)
        for i in range(len(hull)):
            if cross(hull[i], hull[(i + 1) % len(hull)], p) < 0:
                return False
        return True

    return [[3 if grid[r][c] == bg and inside(r, c) else grid[r][c]
             for c in range(w)] for r in range(h)]
